// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockTime) public {
        // Ensure value is 10 ether for the call to not revert
        vm.assume(value == 10 ether);
        // Set the block timestamp to a value higher than pastBlockTime to avoid revert
        vm.assume(blockTime > c.pastBlockTime());
        vm.warp(blockTime);

        // Record pastBlockTime before the call
        uint256 before = c.pastBlockTime();

        // Call fallback via sending value
        (bool success, ) = address(c).call{value: value}("");

        // Rule: If the call succeeds, pastBlockTime must be >= blockTime (strictly > in reference due to the require check, but at least blockTime for reference)
        if (success) {
            assertTrue(c.pastBlockTime() >= blockTime);
        } else {
            // If it reverts, pastBlockTime remains unchanged
            assertTrue(c.pastBlockTime() == before);
        }
    }
}

